import{i as e}from"./index-xqFC_Jp1.js";var t=e({food:()=>n}),n={fukuoka:{eateries:[{id:`ganso-nagahamaya`,name:`Ganso Nagahamaya`,localName:`元祖長浜屋`,area:`Nagahama`,lat:33.59244,lng:130.38661,kind:`casual`,meals:[`breakfast`,`lunch`,`dinner`,`late`],spend:[550,900],order:[{name:`Ramen`,localName:`ラーメン`,price:550,note:`Light, porky tonkotsu broth with very thin noodles; the only dish on the menu`,wiki:`Tonkotsu ramen`},{name:`Kaedama (extra noodles)`,localName:`替玉`,price:150,note:`A second serving of noodles dropped into your leftover soup`}],why:`The fish-market ramen shop that defined Nagahama-style tonkotsu in 1952: one cheap bowl, served in seconds from early morning to late night.`,tip:`Buy a ticket from the machine and say your noodle firmness, such as kata (firm) or nama (barely cooked). Add sesame and pickled ginger.`,praise:[`Remarkably cheap, fast and no-nonsense`,`Lighter broth than many tonkotsu shops`,`Open from early morning until very late`],watchOut:`The broth is milder than modern tonkotsu fans may expect.`,reservation:`walk-in`,reservationNote:`Walk-in; turnover is fast, so any line moves quickly`},{id:`shinshin-tenjin`,name:`Hakata Ramen ShinShin Tenjin Honten`,localName:`博多らーめん ShinShin 天神本店`,area:`Tenjin`,lat:33.5936,lng:130.3983,kind:`casual`,meals:[`lunch`,`dinner`,`late`],spend:[800,1500],order:[{name:`Hakata ramen`,localName:`博多らーめん`,price:850,note:`Creamy but clean pork-bone broth with ultra-thin noodles`,wiki:`Tonkotsu ramen`},{name:`Fried rice`,localName:`焼めし`,note:`Smoky, simple fried rice, a classic partner for the ramen`}],why:`Hugely popular Tenjin ramen shop, packed from lunch until late, known for a smooth, easy-drinking tonkotsu broth and thin noodles.`,tip:`Open late, so it is a favourite after drinks; queues at peak times move quickly. There is also a branch at Hakata Station.`,praise:[`Smooth, well-balanced tonkotsu broth`,`Thin noodles cooked exactly to order`,`Friendly late-night spot in Tenjin`],reservation:`walk-in`,reservationNote:`Walk-in only; expect a short line at lunch and late evening`},{id:`rakutenchi-tenjin`,name:`Motsunabe Rakutenchi Tenjin Honten`,localName:`元祖もつ鍋 楽天地 天神本店`,area:`Tenjin`,lat:33.59158,lng:130.40239,kind:`restaurant`,meals:[`dinner`],spend:[2500,4500],order:[{name:`Motsunabe`,localName:`もつ鍋`,note:`Beef offal hot pot piled high with cabbage, chives and garlic`,wiki:`Motsunabe`},{name:`Champon noodles to finish`,localName:`ちゃんぽん麺`,note:`Thick noodles cooked in the leftover broth to end the meal`}],why:`Long-running motsunabe specialist whose soy-garlic hot pot, crowned with a mountain of chives, is a Fukuoka rite of passage.`,tip:`The set course, with hot pot, sides and noodles, is the easy choice; staff will help cook it at your table.`,praise:[`Generous pots heaped with vegetables`,`Rich, garlicky broth that suits the noodles`,`Lively, good-value group dinner`],reservation:`recommended`,reservationNote:`Book online or by phone for weekend evenings; weekday walk-ins usually seated`},{id:`mizutaki-nagano`,name:`Mizutaki Nagano`,localName:`水たき長野`,area:`Hakata (Tsushimakoji)`,lat:33.59939,lng:130.40279,kind:`restaurant`,meals:[`lunch`,`dinner`],spend:[3500,6e3],order:[{name:`Mizutaki chicken hot pot`,localName:`水たき`,note:`Bone-in chicken in a milky broth; sip the soup first, then add vegetables`},{name:`Zosui rice porridge`,localName:`雑炊`,note:`Rice and egg cooked in the remaining broth to finish`}],why:`A family-run mizutaki house serving its slow-simmered chicken hot pot since 1930, in a homely old-fashioned dining room.`,tip:`Closed Sundays. Staff guide you through the order of eating; the chicken meatballs (tsukune) are a good add-on.`,praise:[`Deep, rich chicken broth`,`Tender chicken and a satisfying porridge finish`,`Old-Hakata atmosphere and kind staff`],reservation:`essential`,reservationNote:`Book by phone well ahead; walk-ins are rarely seated, especially at dinner`},{id:`ganso-hakata-mentaiju`,name:`Ganso Hakata Mentaiju`,localName:`元祖博多めんたい重`,area:`Nishinakasu`,lat:33.5962,lng:130.4039,kind:`casual`,meals:[`breakfast`,`lunch`,`dinner`],spend:[2e3,3500],order:[{name:`Mentaiju`,localName:`めんたい重`,note:`A whole lobe of mentaiko on rice with seaweed, dressed in a special sauce`,wiki:`Pollock roe`},{name:`Mentai nikomi tsukemen`,localName:`めんたい煮こみつけ麺`,note:`Dipping noodles with a hot broth thick with spicy roe`}],why:`Specialist restaurant from a mentaiko maker built around one indulgent rice box of spicy pollock roe, open from breakfast.`,tip:`Lunch queues are long; come for breakfast or a weekday evening. You choose the spice level of the sauce.`,praise:[`Unusual, luxurious way to eat mentaiko`,`Choice of sauce spice levels`,`Early opening for a hearty breakfast`],watchOut:`Lunchtime waits of an hour are common.`,reservation:`recommended`,reservationNote:`Lunch uses a digital queue ticket (on site or online); evening tables can be booked by phone`},{id:`udon-taira`,name:`Udon Taira`,localName:`うどん平`,area:`Sumiyoshi`,lat:33.58313,lng:130.41604,kind:`casual`,meals:[`lunch`],spend:[500,900],order:[{name:`Goboten udon`,localName:`ごぼう天うどん`,note:`Soft udon in clear dashi topped with crisp burdock tempura`,wiki:`Udon`},{name:`Niku gobo udon`,localName:`肉ごぼう天うどん`,note:`The same with sweet simmered beef added`}],why:`Tiny counter beloved by locals for soft, springy Hakata udon in a delicate dashi, topped with freshly fried burdock.`,tip:`Lunch only and closed Sundays; arrive before noon. Help yourself to the green onions.`,praise:[`Delicate, smoky dashi broth`,`Crisp, freshly fried toppings`,`Very cheap, quick local lunch`],watchOut:`Small and busy, with a line at noon.`,reservation:`walk-in`,reservationNote:`Counter seating, walk-in only; the queue moves fast`},{id:`tetsunabe-nakasu`,name:`Tetsunabe Nakasu Honten`,localName:`鉄なべ 中洲本店`,area:`Nakasu`,lat:33.59041,lng:130.40643,kind:`casual`,meals:[`dinner`,`late`],spend:[1500,3e3],order:[{name:`Tetsunabe gyoza`,localName:`鉄なべ餃子`,note:`Small, crisp-bottomed pork dumplings served sizzling in an iron pan`,wiki:`Jiaozi`},{name:`Motsu miso stir-fry`,localName:`ホルモン味噌炒め`,note:`Offal stir-fried with vegetables in sweet miso`}],why:`Iron-pan gyoza specialist whose recipe goes back to a 1960s yatai, frying bite-size dumplings to order near the Nakasu stalls.`,tip:`Dinner only; order a couple of pans per person, with a beer. Handy before or after the riverside yatai.`,praise:[`Crisp, juicy little dumplings`,`Served piping hot in the iron pan`,`Classic Nakasu izakaya atmosphere`],reservation:`recommended`,reservationNote:`Small, so book for weekend evenings or come right at opening`},{id:`kasanoya-dazaifu`,name:`Kasanoya`,localName:`かさの家`,area:`Dazaifu`,lat:33.5194,lng:130.53349,kind:`cafe`,meals:[`breakfast`,`lunch`],spend:[150,1200],order:[{name:`Umegae mochi`,localName:`梅ヶ枝餅`,price:150,note:`Crisp grilled rice cake filled with sweet red bean paste`,wiki:`Umegae mochi`},{name:`Matcha and umegae mochi set`,localName:`抹茶セット`,note:`Hot mochi with a bowl of whisked green tea in the tearoom`}],why:`Old-established teahouse on the approach to Dazaifu Tenmangu, grilling umegae mochi fresh in the front window.`,tip:`Grab one hot from the takeaway window, or sit in the tearoom behind with a garden view.`,praise:[`Mochi grilled crisp and served hot`,`Charming traditional tearoom`,`Cheap, perfect snack on a shrine visit`],reservation:`walk-in`,reservationNote:`Walk-in; the takeaway window line moves quickly`}],dishes:{"Hakata tonkotsu ramen":{price:[600,1200],wiki:`Tonkotsu ramen`},Motsunabe:{price:[1500,3500],wiki:`Motsunabe`},Mizutaki:{price:[3e3,6e3]},Mentaiko:{price:[500,2500],wiki:`Pollock roe`},"Tetsunabe gyoza":{price:[500,900],wiki:`Jiaozi`},"Goboten udon":{price:[450,800],wiki:`Udon`}}}},r=e({food:()=>i}),i={hiroshima:{eateries:[{id:`nagataya`,name:`Okonomiyaki Nagataya`,localName:`お好み焼 長田屋`,area:`Peace Memorial Park (Otemachi)`,lat:34.39422,lng:132.4545,kind:`casual`,meals:[`lunch`,`dinner`],spend:[1200,2500],order:[{name:`Okonomiyaki with soba, pork and egg`,localName:`肉玉そば`,note:`Hiroshima-style layered pancake of cabbage, soba noodles, pork and egg`,wiki:`Okonomiyaki`},{name:`Okonomiyaki with squid and green onion`,localName:`いか天ねぎかけ`,note:`Hiroshima okonomiyaki with fried squid and a pile of green onion`,wiki:`Okonomiyaki`}],why:`Family-run okonomiyaki counter a few steps from the Atomic Bomb Dome, grilling generous Hiroshima-style layers on a big griddle.`,tip:`Closed Tuesdays; queues form at lunch after the museum, so try mid-afternoon or early evening.`,praise:[`Generous, well-built layers with crisp noodles`,`Friendly staff who cook in front of you`,`Handy after the Peace Memorial Museum`],reservation:`walk-in`,reservationNote:`Walk-in only; the line is shortest right at opening or mid-afternoon`},{id:`yagenbori-hassho`,name:`Yagenbori Hassho`,localName:`薬研堀 八昌`,area:`Yagenbori (Nagarekawa)`,lat:34.38952,lng:132.46375,kind:`casual`,meals:[`dinner`],spend:[1200,3e3],order:[{name:`Okonomiyaki with soba`,localName:`そば肉玉`,note:`Hiroshima-style layered cabbage and noodle pancake`,wiki:`Okonomiyaki`},{name:`Teppan-grilled oysters (in season)`,localName:`かき焼き`,note:`Hiroshima oysters cooked on the griddle when in season`}],why:`Long-standing nightlife-district okonomiyaki shop known for a light, fluffy cabbage layer slowly steamed on the griddle.`,tip:`Opens around 16:00; closed Mondays and some Tuesdays. Expect a wait, as each pancake takes 20 to 30 minutes.`,praise:[`Very light, airy cabbage layer`,`Crisp noodles and careful griddle work`,`Worth the wait for okonomiyaki fans`],reservation:`walk-in`,reservationNote:`Walk-in; arrive near opening time for the shortest wait`},{id:`bakudanya-sohonten`,name:`Bakudanya Sohonten`,localName:`廣島つけ麺本舗 ばくだん屋 総本店`,area:`Shintenchi`,lat:34.39144,lng:132.46252,kind:`casual`,meals:[`lunch`,`dinner`],spend:[900,1500],order:[{name:`Hiroshima tsukemen`,localName:`広島つけ麺`,price:950,note:`Cold noodles with cabbage and green onion, dipped in a chilli-sesame sauce`,wiki:`Tsukemen`},{name:`Extra soft-boiled egg`,localName:`半熟玉子`,note:`A soft-boiled marinated egg to add to the bowl`}],why:`Flagship of the chain that popularised Hiroshima tsukemen: cold noodles and cabbage with a chilli dip you can make as fiery as you dare.`,tip:`You choose the spice level; locals start around level 3. Near Okonomi-mura, so handy for a late snack.`,praise:[`Refreshing cold noodles with a real chilli kick`,`You set the heat level yourself`,`Cheap, quick and open late`],watchOut:`Higher spice levels are genuinely painful; start low.`,reservation:`walk-in`,reservationNote:`Walk-in; rarely a long wait outside the lunch peak`},{id:`kunimatsu`,name:`Kunimatsu`,localName:`汁なし担担麺 くにまつ`,area:`Hatchobori`,lat:34.39596,lng:132.46198,kind:`casual`,meals:[`lunch`,`dinner`],spend:[700,1200],order:[{name:`Shiru-nashi tantanmen`,localName:`汁なし担担麺`,note:`Brothless noodles in chilli oil, sesame and numbing sansho pepper`,wiki:`Dandan noodles`},{name:`Small rice to mop up the sauce`,localName:`半ライス`,note:`Half a bowl of rice to mix into the leftover sauce`}],why:`Small counter shop at the heart of Hiroshima's brothless tantanmen boom, with a bright, numbing hit of sansho pepper.`,tip:`Mix the noodles well, at least 30 times, before eating. Weekend hours are limited, so weekdays are safest.`,praise:[`Bold sansho numbness balanced by sesame and chilli`,`Cheap and quick weekday lunch`,`Adding rice to the last of the sauce is a favourite`],reservation:`walk-in`,reservationNote:`Counter shop, walk-in only; weekday lunch can bring a short queue`},{id:`kakiya-miyajima`,name:`Kakiya`,localName:`牡蠣屋`,area:`Miyajima (Omotesando)`,lat:34.29856,lng:132.3217,kind:`restaurant`,meals:[`lunch`],spend:[1500,4e3],order:[{name:`Grilled oysters`,localName:`焼き牡蠣`,note:`Hiroshima oysters grilled in the shell`},{name:`Oyster set meal`,localName:`牡蠣屋定食`,note:`Oysters several ways with oyster rice, soup and sides`},{name:`Fried oysters`,localName:`カキフライ`,note:`Breaded, deep-fried oysters`}],why:`Modern oyster restaurant on Miyajima's main street serving Hiroshima Bay oysters grilled, fried and in rice, with a good sake list.`,tip:`Open roughly 10:00 to 18:00 and may close early when oysters sell out; arrive before noon.`,praise:[`Large, plump Hiroshima oysters`,`Many ways to try oysters in one meal`,`Stylish space and a good sake selection`],watchOut:`Pricier than the street oyster grills along the same lane.`,reservation:`walk-in`,reservationNote:`Usually walk-in; weekends and holidays fill up fastest, so come early`},{id:`anagomeshi-ueno`,name:`Anagomeshi Ueno`,localName:`あなごめし うえの`,area:`Miyajimaguchi`,lat:34.31205,lng:132.3033,kind:`restaurant`,meals:[`breakfast`,`lunch`,`dinner`],spend:[2500,4e3],order:[{name:`Anagomeshi`,localName:`あなごめし`,note:`Grilled conger eel over rice cooked in eel broth`},{name:`Anagomeshi bento box to take away`,localName:`あなごめし弁当`,note:`The same eel rice packed in a wooden box to take away`}],why:`Historic eel shop by the Miyajima ferry pier, cooking rice in conger-eel broth and topping it with smoky grilled anago since 1901.`,tip:`Bento boxes go on sale from about 9:00 and make a great ferry picnic; on Wednesdays it is usually takeaway only.`,praise:[`Smoky, tender eel over flavourful rice`,`Bento holds up well and is good cold`,`Over a century of tradition by the ferry`],watchOut:`Long waits for a table, and anagomeshi is not cheap.`,reservation:`walk-in`,reservationNote:`No reservations for tables; expect to wait, or grab a bento to skip the line`},{id:`momijido-miyajima`,name:`Momijido Honten`,localName:`紅葉堂 本店`,area:`Miyajima (Omotesando)`,lat:34.29781,lng:132.32094,kind:`dessert`,meals:[`breakfast`,`lunch`],spend:[200,600],order:[{name:`Age-momiji (deep-fried momiji manju)`,localName:`揚げもみじ`,price:200,note:`Maple-leaf sponge cake filled with bean paste, battered and deep-fried`,wiki:`Momiji manjū`},{name:`Cheese-filled age-momiji`,localName:`揚げもみじ チーズ`,note:`Fried maple-leaf cake with a melting cheese filling`}],why:`Miyajima confectioner that invented age-momiji, maple-leaf cakes battered and fried to order so they arrive hot and crisp.`,tip:`Eat at the shop rather than on the street; the deer are bold around food.`,praise:[`Crisp batter with a soft cake and sweet filling`,`Served hot right after frying`,`A cheap, fun Miyajima treat`],reservation:`walk-in`,reservationNote:`Buy at the counter; no booking needed`},{id:`hiroshima-andersen`,name:`Hiroshima Andersen`,localName:`広島アンデルセン`,area:`Hondori`,lat:34.39293,lng:132.45829,kind:`bakery`,meals:[`breakfast`,`lunch`],spend:[500,2e3],order:[{name:`Danish pastries`,localName:`デニッシュペストリー`,note:`Flaky laminated pastries with fruit or custard`,wiki:`Danish pastry`},{name:`Sandwiches from the sandwich stand`,localName:`サンドイッチ`,note:`Sandwiches made to order on the shop's own bread`}],why:`The flagship of a bakery chain born in Hiroshima that introduced Danish pastries to Japan, rebuilt on Hondori with a market hall and restaurant.`,tip:`The sandwich stand opens early; the upstairs breakfast is mainly on weekends and holidays.`,praise:[`Wide selection of quality breads and pastries`,`Bright, spacious shop on the main arcade`,`Good spot for a relaxed breakfast`],reservation:`walk-in`,reservationNote:`Walk-in bakery; come early for the best choice of pastries`}],dishes:{"Hiroshima-style okonomiyaki":{price:[900,1800],wiki:`Okonomiyaki`},"Grilled oysters":{price:[500,1500],wiki:`Oyster`},"Anago-meshi":{price:[2200,3500],wiki:`Anago`},"Momiji manju":{price:[100,250],wiki:`Momiji manjū`},"Shiru-nashi tantanmen":{price:[700,1100],wiki:`Dandan noodles`},"Hiroshima tsukemen":{price:[900,1400],wiki:`Tsukemen`}}}},a=e({food:()=>o}),o={kanazawa:{eateries:[{id:`iki-iki-tei-omicho`,name:`Iki Iki Tei`,localName:`いきいき亭 近江町店`,area:`Omicho`,lat:36.57182,lng:136.65654,kind:`casual`,meals:[`breakfast`,`lunch`],spend:[1500,3500],order:[{name:`Iki Iki Tei-don`,localName:`いきいき亭丼`,note:`A seafood bowl of a dozen-plus seasonal toppings from the morning market`,wiki:`Donburi`},{name:`Mini Kanazawa-don with miso soup`,localName:`ミニ金沢丼`,note:`A smaller bowl of local fish over rice, a good first taste`}],why:`Tiny counter at the edge of Omicho Market where the chef piles fish from that morning's auction onto rice bowls in front of you.`,tip:`Opens early, around 7:00; write your name on the sheet by the door if full and they will call you back.`,praise:[`Very fresh, generous seafood toppings`,`Chef explains each fish at the counter`,`Fair prices by market standards`],watchOut:`Only a handful of seats, so waits of 30 to 60 minutes are common by late morning.`,reservation:`walk-in`,reservationNote:`No bookings; put your name on the waiting list and come back when called`},{id:`morimori-sushi-omicho`,name:`Morimori Sushi Omicho`,localName:`もりもり寿し 近江町店`,area:`Omicho`,lat:36.5714,lng:136.65784,kind:`casual`,meals:[`breakfast`,`lunch`],spend:[2e3,5e3],order:[{name:`Nodoguro nigiri`,localName:`のどぐろ`,note:`Rich, fatty blackthroat seaperch, often lightly seared`,wiki:`Blackthroat seaperch`},{name:`Sweet shrimp`,localName:`甘えび`,note:`Soft, sweet Sea of Japan shrimp served raw`},{name:`Crab miso gunkan`,localName:`かに味噌`,note:`Rich crab innards on a seaweed-wrapped rice boat`}],why:`A conveyor-belt sushi shop beside Omicho Market using Hokuriku fish, a cheaper way to try nodoguro, sweet shrimp and seasonal crab.`,tip:`Order from the tablet rather than waiting for plates to pass; plate colours show the price.`,praise:[`Local fish at conveyor-belt prices`,`Easy tablet ordering in English`,`Big pieces of fish on each plate`],watchOut:`Queues build quickly at lunch and on weekends; premium plates add up fast.`,reservation:`walk-in`,reservationNote:`Take a number at the machine by the door; arrive before 11:00 to avoid the queue`},{id:`akadama-honten`,name:`Kanazawa Oden Akadama Honten`,localName:`金澤おでん 赤玉本店`,area:`Katamachi`,lat:36.55964,lng:136.65177,kind:`casual`,meals:[`lunch`,`dinner`],spend:[1500,3500],order:[{name:`Akadama`,localName:`赤玉`,note:`House oden of a quail egg wrapped in red-pepper fishcake`,wiki:`Oden`},{name:`Kani-men (in season)`,localName:`蟹面`,note:`A crab shell packed with crab meat and roe, simmered in oden broth; winter only`},{name:`Daikon and fu`,localName:`大根・車麩`,note:`Broth-soaked radish and wheel-shaped wheat gluten`}],why:`An oden counter in the nightlife district since 1927, simmering Kanazawa-style oden in a clear, savoury dashi.`,tip:`Closed Mondays; the ground-floor counter opens at noon, so it works for a late lunch too.`,praise:[`Deep, clean dashi soaking every piece`,`Classic old-counter atmosphere`,`Good with a glass of local sake`],watchOut:`Popular items, especially kani-men, can sell out by evening.`,reservation:`walk-in`,reservationNote:`Counter seats are first come, first served; late afternoon is quietest`},{id:`turban-curry-sohonten`,name:`Turban Curry Sohonten`,localName:`ターバンカレー 総本店`,area:`Hirosaka`,lat:36.56192,lng:136.65517,kind:`casual`,meals:[`lunch`,`dinner`],spend:[800,1400],order:[{name:`L-size katsu curry`,localName:`Lカツカレー`,note:`Thick dark curry and a pork cutlet on a steel plate with cabbage`,wiki:`Japanese curry`},{name:`Curry with a sausage or egg topping`,localName:`トッピングカレー`,note:`The same curry with extra toppings`}],why:`The original shop of one of the founding Kanazawa curry brands, serving the dense, glossy curry since 1971.`,tip:`A short walk from Korinbo and the 21st Century Museum; weekday afternoons close between lunch and dinner.`,praise:[`Rich, deep curry sauce`,`Crisp pork cutlet and hearty portions`,`Quick, cheap and filling`],reservation:`walk-in`,reservationNote:`Walk-in only; turnover is fast even at lunch`},{id:`hakuichi-higashiyama`,name:`Hakuichi Higashiyama`,localName:`箔一 東山店`,area:`Higashiyama`,lat:36.57231,lng:136.66647,kind:`dessert`,meals:[`lunch`],spend:[900,1500],order:[{name:`Gold-leaf soft serve`,localName:`金箔のかがやきソフト`,price:1e3,note:`Vanilla soft serve wrapped in a whole sheet of edible gold leaf`,wiki:`Soft serve`}],why:`The gold-leaf maker whose soft serve, wrapped in a full sheet of gold, became the signature snack of Higashi Chaya.`,tip:`Eat it inside or by the shop; the leaf sticks to fingers and lips, so take your photo quickly.`,praise:[`Spectacular, very photogenic treat`,`Smooth, creamy soft serve underneath`,`Shop full of gold-leaf crafts to browse`],watchOut:`Expensive for an ice cream; the gold itself adds no flavour.`,reservation:`walk-in`,reservationNote:`Buy at the counter; queues move quickly`},{id:`cafe-fumuroya-kanazawa`,name:`Cafe Fumuroya`,localName:`カフェ 加賀麩不室屋`,area:`Kanazawa Station`,lat:36.5785,lng:136.64761,kind:`cafe`,meals:[`breakfast`,`lunch`],spend:[1200,2500],order:[{name:`Jibu-ni set`,localName:`じぶ煮膳`,note:`Duck and wheat gluten simmered in a thick broth, with rice and sides`,wiki:`Jibu-ni`},{name:`Fu French toast`,localName:`車麩のフレンチトースト`,note:`Wheel-shaped wheat gluten soaked and fried like French toast`}],why:`Cafe of a wheat-gluten (fu) maker founded in 1865, offering an easy, good-value taste of jibu-ni right inside Kanazawa Station.`,tip:`In the Anto West area of the station; handy for a meal before or after the Shinkansen.`,praise:[`Gentle introduction to Kaga cooking`,`Convenient in the station`,`Delicate fu dishes and sweets`],reservation:`walk-in`,reservationNote:`Walk-in; short waits at lunchtime and weekends`},{id:`itaru-honten`,name:`Itaru Honten`,localName:`いたる 本店`,area:`Kakinokibatake`,lat:36.56085,lng:136.65593,kind:`restaurant`,meals:[`dinner`],spend:[5e3,9e3],order:[{name:`Sea of Japan sashimi platter`,localName:`日本海おさしみおけ盛り`,note:`A tub of the day's local sashimi`,wiki:`Sashimi`},{name:`Salt-grilled nodoguro`,localName:`のどぐろ塩焼き`,note:`Whole blackthroat seaperch, grilled until the skin crackles`,wiki:`Blackthroat seaperch`},{name:`Red snow crab`,localName:`紅ズワイかに`,note:`Sweet local crab, served cracked open`}],why:`A lively, long-running izakaya near Korinbo beloved by locals for superb Hokuriku seafood and a deep list of Ishikawa sake.`,tip:`Closed Sundays; the menu changes daily with the catch, so ask the staff what came in.`,praise:[`Outstanding fresh local seafood`,`Buzzing, convivial atmosphere`,`Strong selection of Ishikawa sake`],watchOut:`Nodoguro and crab are priced by market rate and can push the bill up sharply.`,reservation:`recommended`,reservationNote:`Book by phone a few days ahead, especially on Fridays and Saturdays`},{id:`tsubajin`,name:`Tsubajin`,localName:`つば甚`,area:`Teramachi`,lat:36.55521,lng:136.6514,kind:`fine`,meals:[`lunch`,`dinner`],spend:[22e3,4e4],order:[{name:`Kaga kaiseki course`,localName:`加賀料理 会席`,note:`A multi-course seasonal meal in the Kaga tradition`},{name:`Jibu-ni`,localName:`治部煮`,note:`The Kanazawa duck stew, here served as part of the course`,wiki:`Jibu-ni`}],why:`A ryotei founded in 1752 above the Sai River, serving classic Kaga cuisine in private tatami rooms with garden and city views.`,tip:`Closed Wednesdays. Lunch is the more affordable way in; mention dietary needs when booking.`,praise:[`Refined, deeply traditional Kaga cooking`,`Historic rooms and attentive service`,`Beautiful local lacquer and Kutani tableware`],watchOut:`Very expensive, and the formal setting is not for everyone.`,reservation:`essential`,reservationNote:`Reservations only; book by phone or through your hotel at least a few days ahead`}],dishes:{"Jibu-ni":{price:[1200,2500],wiki:`Jibu-ni`},Kaisendon:{price:[2e3,4500],wiki:`Donburi`},"Kanazawa curry":{price:[800,1300],wiki:`Japanese curry`},"Kanazawa oden":{price:[150,600],wiki:`Oden`},Nodoguro:{price:[2e3,6e3],wiki:`Blackthroat seaperch`},"Gold-leaf soft serve":{price:[900,1300],wiki:`Soft serve`}}}},s=e({food:()=>c}),c={okinawa:{eateries:[{id:`shuri-soba`,name:`Shuri Soba`,localName:`首里そば`,area:`Shuri`,lat:26.21754,lng:127.72278,kind:`casual`,meals:[`lunch`],spend:[600,1e3],order:[{name:`Shuri soba`,localName:`首里そば`,note:`Firm, hand-made noodles in a clear bonito-pork broth with pork belly`,wiki:`Okinawa soba`},{name:`Jushi (seasoned rice)`,localName:`じゅーしー`,note:`Okinawan rice cooked with pork, vegetables and broth`}],why:`A beloved little lunch shop near Shuri Castle known for unusually firm, hand-kneaded noodles and a delicate, crystal-clear broth.`,tip:`Lunch only, closed Thursdays and Sundays; noodles often sell out within two hours of the 11:30 opening. Cash only.`,praise:[`Distinctively chewy, firm noodles`,`Light, elegant broth`,`Perfect after visiting Shuri Castle`],watchOut:`Sells out early and closes as soon as the noodles run out.`,reservation:`walk-in`,reservationNote:`No bookings; arrive near opening and expect a short queue`},{id:`yunangi`,name:`Yunangi`,localName:`ゆうなんぎい`,area:`Kumoji`,lat:26.21447,lng:127.68186,kind:`restaurant`,meals:[`lunch`,`dinner`],spend:[1500,4e3],order:[{name:`Rafute`,localName:`ラフテー`,note:`Pork belly braised in awamori, soy and brown sugar`,wiki:`Rafute`},{name:`Fu champuru`,localName:`フーチャンプルー`,note:`Stir-fried wheat gluten with egg and vegetables`},{name:`Goya champuru`,localName:`ゴーヤーチャンプルー`,note:`Bitter melon stir-fried with tofu, egg and pork`}],why:`A homely Okinawan kitchen running since 1970 near Kokusai-dori, cooking classic island dishes the way local grandmothers do.`,tip:`Closed Sundays and holidays. The lunch set meals are excellent value; at dinner order several small plates to share.`,praise:[`Authentic, home-style Okinawan cooking`,`Meltingly tender rafute`,`Warm, old-fashioned atmosphere`],watchOut:`A small room, so evenings fill up fast and the wait can be long.`,reservation:`recommended`,reservationNote:`Book by phone for dinner; lunch is first come, first served`},{id:`urizun-asato`,name:`Urizun`,localName:`うりずん`,area:`Sakaemachi`,lat:26.21736,lng:127.69645,kind:`restaurant`,meals:[`dinner`,`late`],spend:[3e3,5500],order:[{name:`Dururu-ten`,localName:`ドゥル天`,note:`Fried croquette of mashed taro with pork and fishcake, invented here`},{name:`Aged awamori (kusu)`,localName:`古酒`,note:`Long-aged Okinawan rice spirit, smooth and mellow`,wiki:`Awamori`},{name:`Goya champuru`,localName:`ゴーヤーチャンプルー`,note:`Bitter melon stir-fried with tofu, egg and pork`}],why:`A historic awamori izakaya opened in 1972 by Asato station, famed for stocking spirits from every Okinawan distillery and for inventing dururu-ten.`,tip:`Opens at 17:30; ask the staff to suggest awamori by the glass from different islands.`,praise:[`Huge range of awamori, including rare aged spirits`,`Creative and classic Okinawan small plates`,`Atmospheric old wooden interior`],reservation:`recommended`,reservationNote:`Book by phone for weekend evenings; early on weeknights you can often walk in`},{id:`makishi-market-upstairs`,name:`Daiichi Makishi Public Market (upstairs restaurants)`,localName:`第一牧志公設市場`,area:`Kokusai-dori`,lat:26.21455,lng:127.68829,kind:`market`,meals:[`lunch`,`dinner`],spend:[2e3,5e3],order:[{name:`Fish bought downstairs, cooked upstairs`,localName:`持ち上げ`,note:`Pick parrotfish, lobster or shellfish at a stall and have it cooked for you`},{name:`Umibudo (sea grapes)`,localName:`海ぶどう`,note:`Popping strands of seaweed served with a tangy dip`,wiki:`Caulerpa lentillifera`},{name:`Sata andagi`,localName:`サーターアンダギー`,note:`Brown-sugar doughnut balls, sold warm around the market`,wiki:`Sata andagi`}],why:`The fun way to eat at Naha's main market: buy seafood from the stalls below and have one of the upstairs eateries cook it sashimi, fried or in soup.`,tip:`Agree the cooking fee (per person or per dish) before you buy; usually closed on the fourth Sunday of the month.`,praise:[`Very fresh tropical seafood`,`Lively, theatrical market experience`,`Lots of Okinawan produce to try in one place`],watchOut:`Fish is sold by weight and lobster in particular gets expensive quickly; ask prices first.`,reservation:`walk-in`,reservationNote:`Just turn up; weekday late lunch is the calmest time`},{id:`tomari-iyumachi`,name:`Tomari Iyumachi Fish Market`,localName:`泊いゆまち`,area:`Tomari`,lat:26.23007,lng:127.68025,kind:`market`,meals:[`breakfast`,`lunch`],spend:[800,2500],order:[{name:`Sashimi pack`,localName:`刺身盛り`,note:`Tuna, local white fish and squid, packed to eat on the spot`,wiki:`Sashimi`},{name:`Kaisendon`,localName:`海鮮丼`,note:`A seafood rice bowl from one of the market stalls`,wiki:`Donburi`},{name:`Umibudo`,localName:`海ぶどう`,note:`Fresh sea grapes, cheaper here than in town`,wiki:`Caulerpa lentillifera`}],why:`Naha's fishermen's market by Tomari Port, where locals buy tuna and reef fish and visitors grab cheap, ultra-fresh sashimi and rice bowls.`,tip:`Go in the morning for the best choice; there are a few simple tables outside to eat your purchases.`,praise:[`Excellent value fresh tuna and sashimi`,`Real local market feel`,`Handy before a Kerama ferry from Tomari Port`],watchOut:`Little seating and few English signs; some stalls are closed on Sundays and holidays.`,reservation:`walk-in`,reservationNote:`Market stalls, no bookings; arrive before noon`},{id:`blue-seal-makiminato`,name:`Blue Seal Makiminato Honten`,localName:`ブルーシール 牧港本店`,area:`Urasoe`,lat:26.26736,lng:127.7214,kind:`dessert`,meals:[`lunch`,`dinner`,`late`],spend:[400,1e3],order:[{name:`Beni-imo ice cream`,localName:`紅いもアイス`,note:`Purple sweet potato ice cream, the brand's signature flavour`},{name:`Salted chinsuko ice cream`,localName:`塩ちんすこうアイス`,note:`Vanilla with crumbled Okinawan shortbread and sea salt`}],why:`The flagship of the ice cream maker founded for US forces in 1948, a retro American parlour serving tropical Okinawan flavours.`,tip:`On Route 58 between Naha and Chatan, an easy stop on the way to American Village; open late into the evening.`,praise:[`Wide range of island flavours`,`Fun retro American diner feel`,`Cheap, generous scoops`],reservation:`walk-in`,reservationNote:`Order at the counter; no booking needed`},{id:`king-tacos-kin`,name:`King Tacos Kin Honten`,localName:`キングタコス 金武本店`,area:`Kin`,lat:26.4558,lng:127.9264,kind:`casual`,meals:[`lunch`,`dinner`],spend:[800,1300],order:[{name:`Taco rice with cheese and vegetables`,localName:`タコライスチーズ野菜`,price:950,note:`Spiced minced beef, cheese, lettuce and tomato over rice`,wiki:`Taco rice`},{name:`Tacos (4 pieces)`,localName:`タコス`,note:`Crisp-shelled beef tacos with mild salsa`}],why:`The no-frills original near Camp Hansen in Kin, the town where taco rice was invented, serving enormous boxes of it to locals and soldiers.`,tip:`Portions are huge, so one taco rice can feed two; a good stop on the drive between Naha and the north.`,praise:[`Gigantic, filling portions`,`Taco rice at its birthplace`,`Very cheap and quick`],watchOut:`Basic, cramped dining space; many people take away.`,reservation:`walk-in`,reservationNote:`Order at the counter; eat in or take away`},{id:`kishimoto-shokudo`,name:`Kishimoto Shokudo`,localName:`きしもと食堂`,area:`Motobu`,lat:26.66032,lng:127.8959,kind:`casual`,meals:[`lunch`],spend:[700,1200],order:[{name:`Okinawa soba (large)`,localName:`岸本そば 大`,note:`Thick noodles made with traditional wood-ash lye in a smoky bonito broth`,wiki:`Okinawa soba`},{name:`Jushi (seasoned rice)`,localName:`じゅーしー`,note:`Okinawan rice cooked with pork and vegetables`}],why:`A wooden soba house in Motobu town serving Okinawa soba since 1905, still making its noodles the old way with wood-ash lye.`,tip:`About 15 minutes by car from the Churaumi Aquarium; check closing days, and it shuts once the soba runs out.`,praise:[`Rustic, more than century-old shop`,`Hearty, rich bonito broth`,`Classic stop on an aquarium day`],watchOut:`Long weekend queues; the menu is just soba and rice.`,reservation:`walk-in`,reservationNote:`No bookings; come before noon or mid-afternoon to beat the queue`}],dishes:{"Okinawa soba":{price:[600,1e3],wiki:`Okinawa soba`},"Goya champuru":{price:[700,1200],wiki:`Chanpurū`},Rafute:{price:[600,1200],wiki:`Rafute`},"Taco rice":{price:[700,1100],wiki:`Taco rice`},"Sata andagi":{price:[100,200],wiki:`Sata andagi`},Umibudo:{price:[500,1200],wiki:`Caulerpa lentillifera`}}}},l=e({food:()=>u}),u={sapporo:{eateries:[{id:`sumire-susukino`,name:`Sumire Susukino`,localName:`すみれ 札幌すすきの店`,area:`Susukino`,lat:43.05628,lng:141.35358,kind:`casual`,meals:[`dinner`,`late`],spend:[1100,1800],order:[{name:`Miso ramen`,localName:`味噌らーめん`,price:1200,note:`Dark, intense miso broth sealed under hot lard, with firm curly noodles`,wiki:`Ramen`},{name:`Shoyu ramen`,localName:`醤油らーめん`,note:`The soy-sauce version, lighter but just as rich`}],why:`A pillar of Sapporo miso ramen since 1964, whose deep, lard-capped broth inspired a whole school of local shops.`,tip:`On weekdays it opens in the evening only, staying open late; weekends add lunch hours. The soup is very hot, so go slowly.`,praise:[`Deep, savoury miso broth that stays piping hot`,`Springy noodles that hold up to the rich soup`,`Convenient late-night stop in Susukino`],watchOut:`Rich and salty for some; queues build after 21:00.`,reservation:`walk-in`,reservationNote:`Walk-in only; buy a meal ticket and wait in line, which moves fairly quickly`},{id:`menya-saimi`,name:`Menya Saimi`,localName:`麺屋 彩未`,area:`Misono (Toyohira-ku)`,lat:43.03527,lng:141.38192,kind:`casual`,meals:[`lunch`,`dinner`],spend:[1e3,1500],order:[{name:`Miso ramen`,localName:`味噌らーめん`,price:1e3,note:`Balanced miso broth with a hint of grated ginger on the pork`,wiki:`Ramen`},{name:`Shoyu ramen`,localName:`醤油らーめん`,note:`Clear, savoury soy-based bowl`}],why:`Suburban shop whose polished miso ramen is often named the city's best, drawing lines of locals and visitors alike.`,tip:`Near Misono subway station; closed Mondays and shut between lunch and dinner. Arrive 30 minutes before opening.`,praise:[`Rich yet clean miso soup with a gentle ginger lift`,`Consistently excellent bowls`,`Efficient, friendly staff despite the crowds`],watchOut:`Waits of an hour or more are common, and soup can sell out early.`,reservation:`walk-in`,reservationNote:`No reservations; line up outside, ideally before opening`},{id:`daruma-honten`,name:`Jingisukan Daruma Honten`,localName:`成吉思汗 だるま 本店`,area:`Susukino`,lat:43.05486,lng:141.35246,kind:`casual`,meals:[`dinner`,`late`],spend:[2e3,3500],order:[{name:`Jingisukan (mutton)`,localName:`成吉思汗`,note:`Fresh mutton and onions grilled on a dome skillet at your seat`,wiki:`Jingisukan`},{name:`Rice with kimchi`,localName:`ライス・キムチ`,note:`Plain rice to eat with the sauce-dipped mutton`}],why:`Smoky U-shaped counter that has grilled mutton on charcoal-heated skillets since 1954, the city's classic jingisukan.`,tip:`Ask for hot tea at the end to stir into your leftover dipping sauce. Several branches nearby share the queue load.`,praise:[`Tender, barely gamey mutton`,`Old-school counter atmosphere`,`Simple menu that keeps the focus on the meat`],watchOut:`Long evening queues, and your clothes will smell of lamb smoke.`,reservation:`walk-in`,reservationNote:`No bookings; queue outside, shortest right at opening around 17:00`},{id:`garaku`,name:`Soup Curry Garaku`,localName:`スープカレー GARAKU`,area:`Tanukikoji`,lat:43.05805,lng:141.3551,kind:`casual`,meals:[`lunch`,`dinner`],spend:[1400,2300],order:[{name:`Tender chicken leg and vegetable soup curry`,localName:`やわらかチキンレッグと野菜`,note:`A whole stewed chicken leg in spiced broth with roasted vegetables`,wiki:`Japanese curry`},{name:`Pork belly kakuni soup curry`,localName:`豚角煮`,note:`Soy-braised pork belly in the same aromatic curry soup`}],why:`Popular basement soup curry shop with a deep, well-layered broth and generous vegetables, where you set the spice level.`,tip:`Write your name on the list at the entrance, then choose soup, spice level and rice size. Mid-afternoon is quietest.`,praise:[`Rich, aromatic broth with real depth`,`Huge, colourful pile of vegetables`,`Spice and toppings customised to taste`],watchOut:`Expect a queue at peak lunch and dinner times.`,reservation:`walk-in`,reservationNote:`Walk-in; add your name to the waiting list at the door`},{id:`donburi-chaya-nijo`,name:`Donburi Chaya Nijo Market`,localName:`どんぶり茶屋 二条市場店`,area:`Nijo Market`,lat:43.0583,lng:141.3587,kind:`casual`,meals:[`breakfast`,`lunch`],spend:[2e3,5e3],order:[{name:`Sea urchin and salmon roe bowl`,localName:`うにいくら丼`,note:`Rice topped with sweet sea urchin and glossy salmon roe`,wiki:`Donburi`},{name:`Mixed seafood bowl`,localName:`海鮮丼`,note:`Crab, scallop, tuna and roe over rice`}],why:`Market diner piling Hokkaido seafood onto rice bowls from early morning, with dozens of combinations on a picture menu.`,tip:`Opens early, so come for breakfast before the tour groups; prices for sea urchin change with the season.`,praise:[`Very fresh seafood straight from the market`,`Huge choice of bowl combinations`,`Early opening for a seafood breakfast`],watchOut:`Market-area prices are higher than locals pay elsewhere.`,reservation:`walk-in`,reservationNote:`Walk-in; queues are shortest before 8:00`},{id:`nemuro-hanamaru-stellar-place`,name:`Nemuro Hanamaru Stellar Place`,localName:`回転寿司 根室花まる JRタワーステラプレイス店`,area:`Sapporo Station`,lat:43.06799,lng:141.35089,kind:`casual`,meals:[`lunch`,`dinner`],spend:[2e3,4e3],order:[{name:`Hokkaido nigiri: salmon, scallop and surf clam`,localName:`北海道ネタの握り`,note:`Conveyor-belt nigiri using seafood from eastern Hokkaido`,wiki:`Sushi`},{name:`Salmon roe gunkan`,localName:`いくら軍艦`,note:`Seaweed-wrapped rice cup brimming with salmon roe`},{name:`Hanasaki crab miso soup`,localName:`花咲がに鉄砲汁`,note:`Miso soup made with Hanasaki crab`}],why:`Conveyor-belt sushi from the port town of Nemuro with quality far above typical chains, right in the station complex.`,tip:`On the 6th floor of Stellar Place: take a numbered ticket from the machine, then browse the mall while you wait.`,praise:[`Fresh Hokkaido seafood at conveyor-belt prices`,`Order freshly made plates from the chefs`,`Very handy before or after a train`],watchOut:`Waits of an hour or two at peak times are normal.`,reservation:`walk-in`,reservationNote:`No bookings; take a queue ticket at the entrance machine as early as possible`},{id:`rokkatei-sapporo-honten`,name:`Rokkatei Sapporo Main Store`,localName:`六花亭 札幌本店`,area:`Sapporo Station`,lat:43.0659,lng:141.3478,kind:`cafe`,meals:[`breakfast`,`lunch`],spend:[500,1500],order:[{name:`Marusei butter sandwich`,localName:`マルセイバターサンド`,note:`Raisin and white-chocolate butter cream between soft biscuits`},{name:`Hotcakes at the café`,localName:`ホットケーキ`,note:`Thick, fluffy pancakes served in the upstairs café`}],why:`Flagship of Hokkaido's much-loved confectioner, with a full range of sweets downstairs and a bright café upstairs.`,tip:`Some sweets are sold only at this shop or only in the café; boxes of butter sandwiches make an easy souvenir.`,praise:[`Famous butter sandwiches, fresher than at the airport`,`Calm café that is good value`,`Beautiful packaging for gifts`],reservation:`walk-in`,reservationNote:`Walk-in shop and café; the café has a short wait at weekend lunchtimes`},{id:`kani-honke-ekimae`,name:`Kani Honke Sapporo Ekimae`,localName:`かに本家 札幌駅前本店`,area:`Sapporo Station`,lat:43.06567,lng:141.35257,kind:`restaurant`,meals:[`lunch`,`dinner`],spend:[3500,15e3],order:[{name:`Crab kaiseki course`,localName:`かに会席`,note:`Multi-course crab meal: sashimi, boiled, grilled and hot pot`,wiki:`Kaiseki`},{name:`Boiled hairy crab`,localName:`毛がに`,note:`Whole horsehair crab with sweet meat and rich crab miso`,wiki:`Horsehair crab`}],why:`Big, traditional crab house near the station serving king, snow and hairy crab in private tatami rooms and set courses.`,tip:`Lunch sets are far cheaper than dinner courses; the private rooms suit families and groups.`,praise:[`Crab prepared many ways in one meal`,`Attentive, kimono-clad service`,`Private rooms for a special occasion`],watchOut:`Dinner courses are expensive.`,reservation:`recommended`,reservationNote:`Book online or by phone for dinner and weekends; lunch is often fine on the day`}],dishes:{"Sapporo miso ramen":{price:[900,1400],wiki:`Ramen`},Jingisukan:{price:[1500,4e3],wiki:`Jingisukan`},"Soup curry":{price:[1300,2200],wiki:`Japanese curry`},Kaisendon:{price:[2e3,5e3],wiki:`Donburi`},"Hokkaido hairy crab":{price:[4e3,15e3],wiki:`Horsehair crab`},Zangi:{price:[500,1e3]}}}},d=e({food:()=>f}),f={tokyo:{eateries:[{id:`sushi-zanmai-honten`,name:`Sushi Zanmai Honten`,localName:`すしざんまい 本店`,area:`Tsukiji Outer Market`,lat:35.66594,lng:139.77063,kind:`casual`,meals:[`breakfast`,`lunch`,`dinner`,`late`],spend:[2e3,5e3],order:[{name:`Tuna nigiri selection`,localName:`まぐろ三昧`,note:`Assorted tuna nigiri, from lean red meat to fatty toro`,wiki:`Sushi`},{name:`Omakase nigiri set`,note:`Chef-selected assortment of nigiri over vinegared rice`}],why:`Flagship of the Tsukiji sushi chain, open around the clock beside the old market, with tuna-focused nigiri at fair prices.`,tip:`Open 24 hours, so come early morning or late evening to skip the lunch queue.`,praise:[`Generous tuna cuts, including fatty toro, for the price`,`Handy at any hour thanks to round-the-clock opening`,`Friendly, lively counter service`],watchOut:`A chain flagship: reliable, good-value sushi rather than a top-tier counter.`,reservation:`walk-in`,reservationNote:`No booking needed; turn up and expect only a brief wait outside peak meal times`},{id:`maisen-aoyama`,name:`Tonkatsu Maisen Aoyama Honten`,localName:`とんかつ まい泉 青山本店`,area:`Omotesando / Aoyama`,lat:35.66797,lng:139.71153,kind:`restaurant`,meals:[`lunch`,`dinner`],spend:[1800,4e3],order:[{name:`Kurobuta pork loin katsu set`,localName:`黒豚ロースかつ膳`,note:`Breaded, deep-fried Kurobuta (Berkshire) pork loin with rice, soup and cabbage`,wiki:`Tonkatsu`},{name:`Hire katsu sandwich`,localName:`ヒレかつサンド`,note:`Soft white bread with fillet katsu and sweet sauce, crusts off`}],why:`The 1965 original of the famous tonkatsu brand, serving tender cutlets in a converted public bathhouse near Omotesando.`,tip:`Expect a short wait at peak lunch; the takeaway counter sells the katsu sandwiches.`,praise:[`Pork so tender it is said you can cut it with chopsticks`,`Light, crisp panko coating that is not greasy`,`Characterful old bathhouse dining room`],reservation:`walk-in`,reservationNote:`Usually walk-in; arrive before noon or after 14:00 to keep the wait short`},{id:`fuunji`,name:`Fuunji`,localName:`風雲児`,area:`Shinjuku (south)`,lat:35.68689,lng:139.69669,kind:`casual`,meals:[`lunch`,`dinner`],spend:[1e3,1500],order:[{name:`Tsukemen (dipping noodles)`,localName:`つけめん`,price:1e3,note:`Thick cold noodles dipped in a hot, rich chicken-and-fish broth`,wiki:`Tsukemen`},{name:`Special tsukemen with egg and pork`,localName:`特製つけめん`,price:1300,note:`The same dipping noodles topped with a seasoned egg and extra pork`,wiki:`Tsukemen`}],why:`Small counter shop open since 2007, known for thick noodles and a rich chicken-and-fish dipping broth.`,tip:`Buy a ticket from the machine; queues are long at lunch and the shop closes when broth runs out.`,praise:[`Thick, rich dipping broth with a strong fish-powder kick`,`Chewy, satisfying thick noodles in a big portion`,`Ask for a splash of soup to thin the dip at the end`],watchOut:`Tight counter seating with little room for luggage; not a place to linger.`,reservation:`walk-in`,reservationNote:`No reservations; join the line, ideally before opening, then use the ticket machine`},{id:`tsunahachi`,name:`Tsunahachi Sohonten`,localName:`新宿天ぷら つな八 総本店`,area:`Shinjuku (east)`,lat:35.6908,lng:139.70339,kind:`restaurant`,meals:[`lunch`,`dinner`],spend:[2e3,4500],order:[{name:`Tempura set`,localName:`天ぷら膳`,note:`Battered and deep-fried seafood and vegetables with rice and miso soup`,wiki:`Tempura`},{name:`Tendon (tempura rice bowl)`,localName:`天丼`,note:`Tempura over rice, drizzled with a sweet soy sauce`}],why:`Tempura house founded in the 1920s, frying seafood and vegetables to order; sit at the counter to watch the chefs.`,tip:`Lunch sets are the best value; the annex nearby takes the overflow.`,praise:[`Light, crisp batter fried in front of you`,`Good-value lunch sets in central Shinjuku`,`Counter seats give a view of the frying`],reservation:`recommended`,reservationNote:`Book by phone or online for dinner, especially counter seats; lunch is usually walk-in`},{id:`toritake`,name:`Toritake Sohonten`,localName:`鳥竹 総本店`,area:`Shibuya (Dogenzaka)`,lat:35.65805,lng:139.69899,kind:`casual`,meals:[`lunch`,`dinner`],spend:[1500,3500],order:[{name:`Yakitori skewers`,localName:`焼き鳥`,note:`Chicken pieces grilled on skewers over charcoal, with salt or sweet tare`,wiki:`Yakitori`},{name:`Oyakodon`,localName:`親子丼`,note:`Chicken and egg simmered in sweet soy broth over rice`,wiki:`Oyakodon`}],why:`Showa-era yakitori shop by Shibuya Station, in business since 1963 and known for generous charcoal-grilled skewers.`,tip:`Opens from midday, which makes it an easy early dinner; arrive before 18:00 to avoid waiting.`,praise:[`Big, juicy skewers at fair prices`,`Old-school, no-frills Showa atmosphere`,`Oyakodon is a hearty, cheap lunch`],watchOut:`Small, busy and smoky, with tight seating at peak times.`,reservation:`walk-in`,reservationNote:`Generally walk-in; early evening is the easiest time to get seats`},{id:`monja-kondo`,name:`Monja Kondo Honten`,localName:`もんじゃ 近どう 本店`,area:`Tsukishima`,lat:35.66257,lng:139.78115,kind:`casual`,meals:[`lunch`,`dinner`],spend:[1500,3e3],order:[{name:`Mentaiko mochi cheese monja`,localName:`明太もちチーズもんじゃ`,note:`Runny batter with spicy cod roe, rice cake and cheese, cooked on the griddle`,wiki:`Monjayaki`},{name:`Okonomiyaki`,localName:`お好み焼き`,note:`Savoury cabbage pancake cooked on the tabletop griddle`,wiki:`Okonomiyaki`}],why:`Long-running monjayaki shop on Tsukishima Monja Street, often cited as the oldest there; you cook at a tabletop griddle.`,tip:`Staff will show you how to build the batter ring if you ask; the second branch across the street eases waits.`,praise:[`Wide menu of monja fillings, with mentaiko-mochi-cheese a favourite`,`Staff help first-timers get the technique right`,`Fun, hands-on meal for groups`],watchOut:`Weekend evenings bring long waits.`,reservation:`walk-in`,reservationNote:`Mostly walk-in; weekday evenings and lunchtimes have the shortest waits`},{id:`asakusa-kagetsudo`,name:`Asakusa Kagetsudo Honten`,localName:`浅草 花月堂 本店`,area:`Asakusa (Senso-ji)`,lat:35.71461,lng:139.79519,kind:`bakery`,meals:[`breakfast`,`lunch`],spend:[300,1e3],order:[{name:`Jumbo melon pan`,localName:`ジャンボめろんぱん`,price:300,note:`Sweet bun with a crisp cookie-dough crust, named for its melon look`,wiki:`Melonpan`}],why:`Bakery by Senso-ji famous for huge, crisp-topped melon pan baked fresh through the day.`,tip:`Sells out by afternoon; pair it with a morning visit to Senso-ji.`,praise:[`Crunchy cookie crust with a soft, fluffy inside`,`Huge and warm, often straight from the oven`,`Cheap, easy snack while sightseeing`],reservation:`walk-in`,reservationNote:`Walk up to the counter; no booking needed, just come before it sells out`},{id:`kanda-matsuya`,name:`Kanda Matsuya`,localName:`神田まつや`,area:`Kanda`,lat:35.69612,lng:139.76878,kind:`restaurant`,meals:[`lunch`,`dinner`],spend:[1e3,2500],order:[{name:`Mori soba (cold buckwheat noodles)`,localName:`もりそば`,note:`Chilled buckwheat noodles on a bamboo tray with a dipping sauce`,wiki:`Soba`},{name:`Goma soba`,localName:`ごまそば`,note:`Soba with a rich sesame dipping sauce`}],why:`Soba house dating to 1884, serving hand-made buckwheat noodles in a wooden building that survived old Kanda.`,tip:`Closed Sundays; no reservations, but tables turn over quickly.`,praise:[`Firm, fragrant hand-made soba`,`Atmospheric old wooden dining room`,`Classic Edo-style dipping sauce`],watchOut:`Lunch often brings a queue, and you may share a table.`,reservation:`walk-in`,reservationNote:`No bookings; come just before or after the noon rush for a quicker table`}],dishes:{Sushi:{price:[1500,5e3],wiki:`Sushi`},Ramen:{price:[900,1500],wiki:`Ramen`},Monjayaki:{price:[1e3,1800],wiki:`Monjayaki`},Tempura:{price:[1200,3500],wiki:`Tempura`},Yakitori:{price:[150,400],wiki:`Yakitori`},Tonkatsu:{price:[1500,3e3],wiki:`Tonkatsu`}}},kyoto:{eateries:[{id:`nishiki-market`,name:`Nishiki Market`,localName:`錦市場`,area:`Downtown (Shijo)`,lat:35.00503,lng:135.76471,kind:`market`,meals:[`breakfast`,`lunch`],spend:[1e3,3e3],order:[{name:`Dashimaki tamago`,localName:`だし巻き玉子`,note:`Rolled omelette made with dashi stock, soft and juicy`,wiki:`Tamagoyaki`},{name:`Soy milk doughnuts`,localName:`豆乳ドーナツ`,note:`Small, freshly fried doughnuts made with soy milk`},{name:`Pickles tasting`,localName:`京漬物`,note:`Kyoto-style pickled vegetables, often offered to taste`,wiki:`Tsukemono`}],why:`Narrow covered market street that has supplied Kyoto kitchens for centuries, lined with stalls selling local snacks and produce.`,tip:`Most stalls open around 10:00 and close by 17:00; eating while walking is discouraged, so eat at the stall.`,praise:[`Great for grazing many small Kyoto snacks in one walk`,`Fresh dashimaki and pickles worth taking home`,`Covered street, so it works on rainy days`],watchOut:`Very crowded with tourists around midday, and small bites add up quickly.`,reservation:`walk-in`,reservationNote:`Market street, no booking; mid-morning is calmer than lunchtime`},{id:`okutan-nanzenji`,name:`Okutan Nanzenji`,localName:`奥丹 南禅寺`,area:`Nanzen-ji`,lat:35.01243,lng:135.79306,kind:`restaurant`,meals:[`lunch`],spend:[3500,4500],order:[{name:`Yudofu set`,localName:`湯どうふ一通り`,note:`Tofu simmered in kelp broth, with sesame tofu, tempura and rice`}],why:`Tofu restaurant with roots in the 1600s, serving a single simmered-tofu set in a garden setting by Nanzen-ji.`,tip:`Lunch only and closed Thursdays; arrive at opening to avoid the noon queue.`,praise:[`Silky, delicate tofu in a calm garden setting`,`Peaceful tatami seating away from the crowds`,`A classic temple-district meal near Nanzen-ji`],watchOut:`Pricey for a set that is mostly tofu, and the flavours are very subtle.`,reservation:`walk-in`,reservationNote:`No booking needed; be there at opening for the shortest wait`},{id:`izuu`,name:`Izuu`,localName:`いづう`,area:`Gion`,lat:35.00486,lng:135.7745,kind:`restaurant`,meals:[`lunch`,`dinner`],spend:[2500,5e3],order:[{name:`Saba sugata-zushi (pressed mackerel sushi)`,localName:`鯖姿寿司`,note:`Vinegar-cured mackerel pressed onto rice and wrapped in kelp`},{name:`Inari-zushi`,localName:`いなり寿司`,note:`Sweet fried tofu pouches stuffed with sushi rice`,wiki:`Inarizushi`}],why:`Kyoto-style sushi shop founded in 1781, best known for its cured mackerel pressed sushi wrapped in kelp.`,tip:`Half portions are available; it also sells takeaway boxes at the Isetan basement by Kyoto Station.`,praise:[`Rich, well-balanced cured mackerel on firm rice`,`Old Gion townhouse atmosphere`,`Takeaway boxes travel well for a train picnic`],watchOut:`Pricey for a few pieces of pressed sushi.`,reservation:`walk-in`,reservationNote:`Usually walk-in; evenings tend to be quieter than weekend lunch`},{id:`saryo-tsujiri`,name:`Saryo Tsujiri Gion Honten`,localName:`茶寮都路里 祇園本店`,area:`Gion (Shijo-dori)`,lat:35.0037,lng:135.77471,kind:`dessert`,meals:[`lunch`],spend:[1e3,2e3],order:[{name:`Tokusen Tsujiri matcha parfait`,localName:`特選都路里パフェ`,note:`Tall glass of matcha ice cream, jelly, cream, red beans and rice dumplings`},{name:`Matcha soft serve`,localName:`抹茶ソフト`,note:`Soft-serve ice cream made with green tea`}],why:`Tea room above the Gion shop of an Uji tea merchant, known for tall matcha parfaits layered with jelly, cream and red beans.`,tip:`Queues build in the afternoon; go right at opening or after 18:00.`,praise:[`Deep, slightly bitter matcha flavour, not overly sweet`,`Big, layered parfaits worth sharing`,`Long-established Uji tea name in Gion`],reservation:`walk-in`,reservationNote:`No reservations; join the queue, which is shortest at opening or in the evening`},{id:`omen-ginkakuji`,name:`Omen Ginkakuji Honten`,localName:`おめん 銀閣寺本店`,area:`Ginkaku-ji / Philosopher's Path`,lat:35.02616,lng:135.79495,kind:`casual`,meals:[`lunch`,`dinner`],spend:[1300,2500],order:[{name:`Omen udon with seasonal vegetables`,localName:`おめん`,note:`Thick udon dipped in warm broth with sesame and seasonal vegetables`,wiki:`Udon`},{name:`Obanzai side dishes`,localName:`おばんざい`,note:`Small plates of everyday Kyoto home cooking`,wiki:`Obanzai`}],why:`Udon shop near Ginkaku-ji since 1967; thick noodles come with a dipping broth, sesame and a plate of Kyoto vegetables.`,tip:`Closed Thursdays; a good stop at the north end of the Philosopher's Path.`,praise:[`Chewy, thick udon with fresh, colourful vegetables`,`Fun to add sesame and toppings yourself`,`Welcome stop after walking the Philosopher's Path`],reservation:`walk-in`,reservationNote:`Usually walk-in; weekend lunch can mean a short wait for a table`},{id:`honke-daiichi-asahi`,name:`Honke Daiichi-asahi`,localName:`本家 第一旭 たかばし本店`,area:`Kyoto Station`,lat:34.98669,lng:135.76249,kind:`casual`,meals:[`breakfast`,`lunch`,`dinner`,`late`],spend:[900,1500],order:[{name:`Tokusei ramen (extra pork and noodles)`,localName:`特製ラーメン`,note:`Kyoto soy-pork ramen with extra noodles and extra pork slices`,wiki:`Ramen`},{name:`Ramen`,localName:`ラーメン`,note:`Thin noodles in soy-pork broth with pork and green onion`,wiki:`Ramen`}],why:`Long-running ramen shop near Kyoto Station serving pork-and-soy Kyoto ramen with thin noodles and green onion from early morning.`,tip:`Opens around 06:00 and closed Thursdays; mid-morning is the quietest time.`,praise:[`Light yet savoury soy-pork broth`,`Generous slices of pork and green onion`,`Rare chance for ramen early in the morning`],watchOut:`Queues often stretch along the street, especially at weekends.`,reservation:`walk-in`,reservationNote:`No bookings; join the street queue, which moves fastest mid-morning`},{id:`inoda-coffee-honten`,name:`Inoda Coffee Honten`,localName:`イノダコーヒ 本店`,area:`Downtown (Sanjo)`,lat:35.00817,lng:135.76319,kind:`cafe`,meals:[`breakfast`,`lunch`],spend:[1200,2500],order:[{name:`Kyoto breakfast plate`,localName:`京の朝食`,price:1800,note:`Ham, scrambled egg, croissant, salad and juice served together`},{name:`Arabia no Shinju blend coffee`,localName:`アラビアの真珠`,note:`House coffee blend, served with milk and sugar unless you ask`}],why:`Kyoto coffee house founded in 1940, a local breakfast ritual with ham, eggs, croissant and coffee served with milk and sugar.`,tip:`Breakfast starts at 07:00; ask for black coffee if you do not want it pre-sweetened.`,praise:[`Charming, old-fashioned coffee house atmosphere`,`Generous, classic Western-style breakfast`,`Attentive waiters in white jackets`],reservation:`walk-in`,reservationNote:`Walk-in café; weekend mornings may mean a short wait for a table`},{id:`kikunoi-honten`,name:`Kikunoi Honten`,localName:`菊乃井 本店`,area:`Higashiyama (Maruyama Park)`,lat:35.00137,lng:135.78226,kind:`fine`,meals:[`lunch`,`dinner`],spend:[2e4,5e4],order:[{name:`Seasonal kaiseki course`,localName:`懐石料理`,note:`A multi-course traditional Japanese meal built around the season`,wiki:`Kaiseki`}],why:`Ryotei run by the Murata family for over a century, serving seasonal kaiseki in private tatami rooms below Kodai-ji.`,tip:`Book weeks to months ahead, often via a hotel concierge; lunch is the more affordable way in.`,praise:[`Beautifully presented, highly seasonal courses`,`Private tatami rooms with garden views`,`Warm, polished traditional hospitality`],watchOut:`One of Kyoto's most expensive meals, and booking well ahead is essential.`,reservation:`essential`,reservationNote:`Reservation only; secure lunch or dinner well ahead through the restaurant or your hotel`}],dishes:{Kaiseki:{price:[6e3,2e4],wiki:`Kaiseki`},Yudofu:{price:[2500,4500]},"Matcha sweets":{price:[500,1800],wiki:`Matcha`},Yatsuhashi:{price:[500,1200],wiki:`Yatsuhashi`},"Saba-zushi":{price:[1500,4e3]},Obanzai:{price:[1e3,2500],wiki:`Obanzai`}}},osaka:{eateries:[{id:`wanaka-sennichimae`,name:`Takoyaki Doraku Wanaka Sennichimae Honten`,localName:`たこ焼道楽 わなか 千日前本店`,area:`Namba (Sennichimae)`,lat:34.66521,lng:135.5034,kind:`street`,meals:[`lunch`,`dinner`,`late`],spend:[600,1200],order:[{name:`Takoyaki (8 pieces)`,localName:`たこ焼き`,price:700,note:`Wheat-batter balls with octopus, cooked in round moulds and sauced`,wiki:`Takoyaki`},{name:`Takoyaki senbei`,localName:`たこせん`,note:`Takoyaki pressed between crisp prawn crackers`}],why:`Takoyaki stand near Namba Grand Kagetsu, griddling crisp-shelled octopus balls in copper pans with seating upstairs.`,tip:`Open until 23:00, and from the morning at weekends; try the salt or soy versions alongside the classic sauce.`,praise:[`Crisp outside and creamy, molten inside`,`Several sauce styles to try side by side`,`Quick, cheap snack in the heart of Namba`],watchOut:`Centres come out scalding hot, so let them rest a moment.`,reservation:`walk-in`,reservationNote:`Order at the stand; no bookings and the line moves quickly`},{id:`mizuno-dotonbori`,name:`Mizuno`,localName:`美津の`,area:`Dotonbori`,lat:34.66837,lng:135.50322,kind:`restaurant`,meals:[`lunch`,`dinner`],spend:[1500,3e3],order:[{name:`Yamaimo-yaki (yam okonomiyaki)`,localName:`山芋焼`,note:`Okonomiyaki bound with grated mountain yam instead of flour`,wiki:`Okonomiyaki`},{name:`Mizuno-yaki`,localName:`美津の焼`,note:`The house okonomiyaki loaded with pork, squid, scallops and more`,wiki:`Okonomiyaki`}],why:`Family-run okonomiyaki shop in Dotonbori since 1945, known for a fluffy version made with grated mountain yam.`,tip:`No reservations; queue near opening at 11:00 to keep the wait short.`,praise:[`Unusually light, fluffy okonomiyaki thanks to the yam`,`Cooked for you on the griddle at your table`,`Family-run feel in the middle of Dotonbori`],watchOut:`Long queues are common, especially at weekends.`,reservation:`walk-in`,reservationNote:`Queue only; weekday mid-afternoons are usually calmer than weekends`},{id:`daruma-shinsekai`,name:`Kushikatsu Daruma Shinsekai Sohonten`,localName:`串かつだるま 新世界総本店`,area:`Shinsekai`,lat:34.65162,lng:135.50624,kind:`casual`,meals:[`lunch`,`dinner`],spend:[1500,3e3],order:[{name:`Original beef kushikatsu`,localName:`元祖串かつ`,note:`Breaded, deep-fried beef skewer dipped in thin sauce`,wiki:`Kushikatsu`},{name:`Assorted skewer set`,localName:`セット`,note:`A mixed set of fried skewers to try several fillings`,wiki:`Kushikatsu`}],why:`The 1929 founding shop of Osaka's best-known kushikatsu brand, frying skewers to order under Tsutenkaku tower.`,tip:`No double-dipping in the shared sauce; use the cabbage to scoop more.`,praise:[`Thin, crisp batter on freshly fried skewers`,`Huge choice of meat, seafood and vegetables`,`Lively Shinsekai atmosphere`],watchOut:`Busy with tourists, so queues at the founding shop are common.`,reservation:`walk-in`,reservationNote:`Walk-in only; weekday afternoons have the shortest queue`},{id:`usamitei-matsubaya`,name:`Usamitei Matsubaya`,localName:`うさみ亭マツバヤ`,area:`Shinsaibashi / Minamisenba`,lat:34.67796,lng:135.50232,kind:`casual`,meals:[`lunch`],spend:[800,1500],order:[{name:`Kitsune udon`,localName:`きつねうどん`,note:`Udon in light dashi topped with sweet simmered fried tofu`},{name:`Oji-ya udon hot pot`,localName:`おじやうどん`,note:`Udon simmered in a pot with rice, egg and toppings`}],why:`Udon shop founded in 1893 that is credited with inventing kitsune udon, topped with sweet simmered fried tofu.`,tip:`Daytime only and closed Sundays and holidays.`,praise:[`Sweet, juicy fried tofu in a delicate dashi broth`,`A piece of Osaka food history at a low price`,`Homely, unpretentious shop`],reservation:`walk-in`,reservationNote:`Walk-in; arrive before noon to beat the office lunch crowd`},{id:`551-horai-honten`,name:`551 Horai Honten`,localName:`551蓬莱 本店`,area:`Namba (Ebisubashi-suji)`,lat:34.66647,lng:135.50126,kind:`street`,meals:[`breakfast`,`lunch`,`dinner`],spend:[500,1500],order:[{name:`Butaman (pork bun)`,localName:`豚まん`,note:`Steamed bun filled with pork and onion`,wiki:`Baozi`},{name:`Shumai`,localName:`焼売`,note:`Steamed pork dumplings with an open top`,wiki:`Shumai`}],why:`Head shop of the Osaka pork-bun maker, where buns are folded by hand in view; there is a sit-down restaurant upstairs.`,tip:`Buns are sold in pairs; the takeaway line moves fast.`,praise:[`Juicy pork and onion filling in a fluffy bun`,`Great value, and a classic Osaka souvenir`,`Fun to watch the buns being folded`],watchOut:`The buns have a strong onion smell, so think twice before eating them on trains.`,reservation:`walk-in`,reservationNote:`No booking needed; just join the takeaway line`},{id:`kuromon-market`,name:`Kuromon Market`,localName:`黒門市場`,area:`Nipponbashi`,lat:34.66533,lng:135.50698,kind:`market`,meals:[`breakfast`,`lunch`],spend:[1500,4e3],order:[{name:`Grilled seafood skewers`,localName:`焼き海鮮`,note:`Scallops, prawns or crab grilled at the stall`},{name:`Sashimi and sushi`,localName:`刺身`,note:`Sliced raw fish and sushi from the market stalls`,wiki:`Sashimi`},{name:`Fresh fruit`,localName:`フルーツ`,note:`Cut Japanese fruit, often premium strawberries or melon`}],why:`Covered market street that has fed Osaka cooks for about two centuries, now packed with stalls grilling seafood to eat on the spot.`,tip:`Go in the morning; many stalls close by late afternoon and prices are higher than in ordinary shops.`,praise:[`Wide choice of seafood grilled on the spot`,`Fresh sushi and sashimi to eat right away`,`Lively place to graze Osaka produce`],watchOut:`Can feel touristy and very crowded around midday.`,reservation:`walk-in`,reservationNote:`Market, no booking; mornings are less crowded`},{id:`meoto-zenzai`,name:`Hozenji Meoto Zenzai`,localName:`法善寺 夫婦善哉`,area:`Hozenji Yokocho`,lat:34.66779,lng:135.5024,kind:`dessert`,meals:[`lunch`,`dinner`],spend:[800,1e3],order:[{name:`Meoto zenzai (sweet red bean soup, two bowls)`,localName:`夫婦善哉`,price:800,note:`Sweet red bean soup with rice cake, served in two small bowls`,wiki:`Red bean soup`}],why:`Sweet shop founded in 1883 by Hozen-ji temple, serving red bean soup split into two bowls, made famous by a 1940 novel.`,tip:`Shaved ice versions appear in summer; visit the moss-covered statue next door.`,praise:[`Charming story behind the two small bowls`,`Smooth, comforting red bean soup with rice cake`,`Tucked into an atmospheric old alley`],watchOut:`Very sweet, and the portions are small for the price.`,reservation:`walk-in`,reservationNote:`Walk-in; a small room, so expect a brief wait at busy times`},{id:`tsuruichi`,name:`Yakiniku Tsuruichi Honten`,localName:`焼肉 鶴一 本店`,area:`Tsuruhashi`,lat:34.66569,lng:135.5291,kind:`restaurant`,meals:[`lunch`,`dinner`],spend:[3e3,6e3],order:[{name:`Kalbi`,localName:`カルビ`,note:`Marinated beef short rib grilled at the table`},{name:`Assorted horumon`,localName:`ホルモン`,note:`Mixed beef and pork offal grilled over charcoal`,wiki:`Horumonyaki`}],why:`Yakiniku house founded in 1949 in Tsuruhashi's Korean quarter, grilling beef and offal over charcoal with a long-unchanged sauce.`,tip:`Steps from Tsuruhashi Station; the surrounding market alleys are good for kimchi and snacks.`,praise:[`Tasty marinated beef and offal over real charcoal`,`Long-loved house dipping sauce`,`Old-school Tsuruhashi atmosphere`],watchOut:`Smoky inside; expect your clothes to smell of the grill afterwards.`,reservation:`recommended`,reservationNote:`Book by phone for dinner or weekends; weekday lunch is usually walk-in`}],dishes:{Takoyaki:{price:[500,900],wiki:`Takoyaki`},Okonomiyaki:{price:[900,1800],wiki:`Okonomiyaki`},Kushikatsu:{price:[100,300],wiki:`Kushikatsu`},"Kitsune udon":{price:[600,1e3],wiki:`Udon`},Butaman:{price:[200,400],wiki:`Baozi`},Horumon:{price:[500,1200],wiki:`Horumonyaki`}}}};export{r as a,a as i,l as n,t as o,s as r,d as t};